function aircraftAlias(value){return String(value||'').toUpperCase().replace(/BOEING|AIRBUS|EMBRAER|COMAC|DE HAVILLAND|BOMBARDIER/g,'').replace(/[^A-Z0-9]/g,'');}
// Legacy labels explicitly confirmed by the user; ATR 72 alone is not a universal -600 designation.
const aircraftConfirmedLabels={'DHC8400DASH8Q':'De Havilland Dash 8-400','ATR72':'ATR 72-600'};
function catalogAircraft(value){const key=aircraftAlias(value);if(aircraftConfirmedLabels[key])return aircraftCatalog.find(a=>a.name===aircraftConfirmedLabels[key]);return aircraftCatalog.find(a=>[a.name,...a.aliases].some(alias=>aircraftAlias(alias)===key));}
